import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第十二卦 否 地天否 乾上坤下","description":"周易 - 第十二卦 否 地天否 乾上坤下","frontmatter":{"title":"第十二卦 否 地天否 乾上坤下","description":"周易 - 第十二卦 否 地天否 乾上坤下"},"headers":[],"relativePath":"zh/classics/zhouyi/013.md","filePath":"zh/classics/zhouyi/013.md"}'),l={name:"zh/classics/zhouyi/013.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="否" tabindex="-1">否 <a class="header-anchor" href="#否" aria-label="Permalink to “否”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>否之匪人，不利君子贞，大往小来。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>否之匪人，不利君子贞。大往小来，则是天地不交，而万物不通也；上下不交，而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子。小人道长，君子道消也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>天地不交，否；君子以俭德辟难，不可荣以禄。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>拔茅茹，以其夤，贞吉 亨。象曰：拔茅贞吉，志在君也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>包承。小人吉，大人否亨。象曰：大人否亨，不乱群也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>包羞。象曰：包羞，位不当也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>有命无咎，畴离祉。象曰：有命无咎，志行也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>休否，大人吉。其亡其亡，系于苞桑。象曰：大人之吉，位正当也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>倾否，先否后喜。象曰：否终则倾，何可长也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
